    ControlFlow::Continue(delay_ms) => {
        token = match self.error_handling_line.try_acquire_token().or_token(token) {
            AcquireOutcome::Success(new_token) => {
                xpcom_async::sleep(delay_ms).await?;
                Some(new_token)
            }
